python3 -c "
target='.....((((((.((((((((....))))))).)))((((((((((....)))))))))))))).....'
# Print each position with index and char, and its pair partner
stack=[]; pairs={}
for i,c in enumerate(target):
    if c=='(': stack.append(i)
    elif c==')':
        j=stack.pop(); pairs[j]=i; pairs[i]=j
for i in range(68):
    p = pairs.get(i, '.')
    print(f'{i:2d} {target[i]} -> {p}')
" | sed -n '1,45p'

python3 -c "
mfe='.....((((((..(((((((....)))))))..))((((((((((....)))))))))))))).....'
target='.....((((((.((((((((....))))))).)))((((((((((....)))))))))))))).....'
# parse mfe pairs
stack=[]; pm={}
for i,c in enumerate(mfe):
    if c=='(': stack.append(i)
    elif c==')':
        j=stack.pop(); pm[j]=i; pm[i]=j
# parse target pairs
stack=[]; pt={}
for i,c in enumerate(target):
    if c=='(': stack.append(i)
    elif c==')':
        j=stack.pop(); pt[j]=i; pt[i]=j
# differences
print('target pairs:', sorted((i,pt[i]) for i in range(68) if i<pt.get(i,-1) and i in pt))
print('mfe pairs:   ', sorted((i,pm[i]) for i in range(68) if i<pm.get(i,-1) and i in pm))
# what changed
tp=set((i,pt[i]) for i in range(68) if i<pt.get(i,-1) and i in pt)
mp=set((i,pm[i]) for i in range(68) if i<pm.get(i,-1) and i in pm)
print('only in target:', sorted(tp-mp))
print('only in mfe:   ', sorted(mp-tp))
"

